using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;using System.Web.Script.Serialization;using D=System.Drawing;
class FontControlsTests {
 static int checks,failures;static void Check(bool v,string n){checks++;Console.WriteLine((v?"PASS ":"FAIL ")+n);if(!v)failures++;}static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).GetValue(o);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(o,a);}static IEnumerable<DependencyObject> Tree(DependencyObject o){yield return o;for(int i=0;i<VisualTreeHelper.GetChildrenCount(o);i++)foreach(var v in Tree(VisualTreeHelper.GetChild(o,i)))yield return v;}static T Named<T>(DependencyObject w,string n)where T:DependencyObject{Pump();return Tree(w).OfType<T>().First(c=>System.Windows.Automation.AutomationProperties.GetName(c)==n);}static void Pump(){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(100)};timer.Tick+=(s,e)=>{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}static void Click(Window w,string n){Tree(w).OfType<Button>().First(b=>Convert.ToString(b.Content)==n).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();}static void Shot(Window w,string path){w.UpdateLayout();var root=(FrameworkElement)w.Content;var b=new RenderTargetBitmap((int)root.ActualWidth,(int)root.ActualHeight,96,96,PixelFormats.Pbgra32);b.Render(root);var e=new PngBitmapEncoder();e.Frames.Add(BitmapFrame.Create(b));using(var f=File.Create(path))e.Save(f);}

 static MonitorConfig Draft(Window w){return (MonitorConfig)Get(w,"taskbarDraft");}
 static string Render(MonitorConfig cfg){using(var b=TaskbarPainter.Preview(cfg,new SystemSample{Cpu=46,MemoryUsed=8,MemoryTotal=16},100))using(var m=new MemoryStream()){b.Save(m,D.Imaging.ImageFormat.Png);return Convert.ToBase64String(m.ToArray());}}
 [STAThread]static int Main(string[] args){Directory.CreateDirectory(args[0]);Window pet=null;var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};try{
 pet=(Window)Activator.CreateInstance(typeof(ConanPet),true);var assistant=(AssistantRuntime)Get(pet,"assistant");assistant.Config.Monitor.Quota.Enabled=false;((VoiceRuntime)Get(pet,"voices")).Settings.Enabled=false;var actual=assistant.Config.Monitor;actual.TaskbarItems=new List<string>{"cpu","memory"};actual.Appearance.AutoFit=false;actual.Appearance.AutoRows=false;actual.Appearance.Rows=1;actual.Appearance.FontName="Microsoft YaHei UI";actual.Appearance.LatinFontName="Arial";actual.Appearance.FontSize=12;actual.Appearance.LatinFontSize=12;actual.Appearance.Bold=actual.Appearance.Italic=false;actual.Appearance.LatinBold=actual.Appearance.LatinItalic=false;assistant.Save();pet.Show();Pump();((System.Threading.Timer)Get(pet,"assistantTimer")).Change(-1,-1);((DispatcherTimer)Get(pet,"ticker")).Stop();((DispatcherTimer)Get(pet,"skillTicker")).Stop();Call(pet,"OpenTerminal");var w=(TerminalWindow)Get(pet,"terminal");w.ShowPage("任务栏外观");Click(w,"配色与文字");
 foreach(string language in new[]{"中文","英文"})foreach(string style in new[]{"粗体","斜体"}){var toggle=Named<CheckBox>(w,language+style);var previous=((Image)Get(w,"taskbarPreview")).Source;toggle.IsChecked=true;Pump();var a=Draft(w).Appearance;bool active=language=="中文"?(style=="粗体"?a.Bold:a.Italic):(style=="粗体"?a.LatinBold==true:a.LatinItalic==true);Check(active,language+style+" font-picker property update reaches preview");Check(!Object.ReferenceEquals(previous,((Image)Get(w,"taskbarPreview")).Source),language+style+" refreshes visible preview source");toggle.IsChecked=false;Pump();a=Draft(w).Appearance;bool cleared=language=="中文"?(style=="粗体"?!a.Bold:!a.Italic):(style=="粗体"?a.LatinBold==false:a.LatinItalic==false);Check(cleared,language+style+" property reset reaches preview");}
 foreach(string language in new[]{"中文","英文"}){string before=Render(Draft(w));Named<Button>(w,language+"字号增加").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();Check(Render(Draft(w))!=before,language+" size changes native rendered image");foreach(string style in new[]{"粗体","斜体"}){before=Render(Draft(w));var box=Named<CheckBox>(w,language+style);box.IsChecked=true;box.RaiseEvent(new RoutedEventArgs(CheckBox.ClickEvent));Pump();Check(Render(Draft(w))!=before,language+style+" changes native rendered image");}before=Render(Draft(w));Named<TextBox>(w,language+"字体名称").Text=language=="中文"?"SimSun":"Consolas";Pump();Check(Render(Draft(w))!=before,language+" font changes native rendered image");}
 Click(w,"应用并保存任务栏外观");Check(actual.Appearance.FontName=="SimSun"&&actual.Appearance.LatinFontName=="Consolas"&&actual.Appearance.Bold&&actual.Appearance.Italic&&actual.Appearance.LatinBold==true&&actual.Appearance.LatinItalic==true,"font choices and styles apply to real configuration");
 var json=new JavaScriptSerializer();var reloaded=new AssistantRuntime(AppDomain.CurrentDomain.BaseDirectory);Check(json.Serialize(reloaded.Config.Monitor.Appearance)==json.Serialize(actual.Appearance),"font settings survive real runtime reload");reloaded.Telemetry.Dispose();
 }catch(Exception e){Console.WriteLine("FAIL "+e);failures++;}finally{if(pet!=null)pet.Close();app.Shutdown();}File.WriteAllText(Path.Combine(args[0],"font-controls-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures,isolated_settings=true}));return failures==0?0:1;}
}
